const panel=document.querySelector('#menu-panel');
function showMenu(category){panel.replaceChildren(...menu[category].map(([name,description,price])=>{const item=document.createElement('article');item.className='menu-item';const h=document.createElement('h3');h.textContent=name;const p=document.createElement('p');p.textContent=description;const cost=document.createElement('span');cost.className='price';cost.textContent=price;item.append(h,p,cost);return item;}));panel.setAttribute('aria-labelledby','tab-'+category);document.querySelectorAll('[role=tab]').forEach(b=>{const active=b.dataset.category===category;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});if(window.ScrollTrigger)ScrollTrigger.refresh();}
showMenu('picar');
const tabs=[...document.querySelectorAll('[role=tab]')];tabs.forEach((b,index)=>{b.addEventListener('click',()=>showMenu(b.dataset.category));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;if(e.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();showMenu(tabs[next].dataset.category);}});});
document.querySelector('.wok-builder').addEventListener('submit',e=>e.preventDefault());
const base=document.querySelector('#base'),protein=document.querySelector('#protein'),sauce=document.querySelector('#sauce');
function updateWok(){document.querySelector('#wok-price').textContent=new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(8.5+Number(protein.value)+Number(sauce.value));document.querySelector('#wok-summary').textContent=[base.value,protein.selectedOptions[0].text.split(' (+')[0],sauce.selectedOptions[0].text.split(' (+')[0]].join(' · ');}
[base,protein,sauce].forEach(s=>s.addEventListener('change',updateWok));
const menuToggle=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
function closeNav(){navigation.classList.remove('open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir navegación');}
menuToggle.addEventListener('click',()=>{const open=navigation.classList.toggle('open');menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Cerrar navegación':'Abrir navegación');});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});
for(const [trigger,id] of [['open-menu','menu-dialog'],['open-credits','credits-dialog']]){const dialog=document.getElementById(id);document.getElementById(trigger).addEventListener('click',()=>dialog.showModal());dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
// Photography is given depth with perspective; reduced-motion keeps all content static and visible.
if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{gsap.from('.hero-copy > *',{y:32,opacity:0,duration:1.1,stagger:.12,ease:'power3.out',delay:.15});gsap.from('.hero-picture img',{scale:1.08,duration:2.2,ease:'power2.out'});gsap.to('.hero-picture',{y:110,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true}});gsap.utils.toArray('.reveal').forEach(el=>gsap.from(el,{y:36,opacity:0,duration:.9,ease:'power2.out',scrollTrigger:{trigger:el,start:'top 93%',once:true}}));});mm.add('(min-width: 761px) and (prefers-reduced-motion: no-preference)',()=>{const tl=gsap.timeline({scrollTrigger:{trigger:'.dish-story',start:'top top',end:'+=950',pin:'.dish-stage',scrub:1,anticipatePin:1}});tl.fromTo('.dish-image',{rotation:-12,rotationX:18,y:55,scale:.9},{rotation:5,rotationX:0,y:-20,scale:1.1,ease:'none'},0).fromTo('.dish-watermark',{x:100},{x:-140,ease:'none'},0).fromTo('.dish-note',{y:70,opacity:.25},{y:0,opacity:1,duration:.4},0);});mm.add('(hover: hover) and (prefers-reduced-motion: no-preference)',()=>{const target=document.querySelector('.dish-note');const x=gsap.quickTo(target,'rotationY',{duration:.5,ease:'power2.out'}),y=gsap.quickTo(target,'rotationX',{duration:.5,ease:'power2.out'});const move=e=>{const r=target.getBoundingClientRect();x((e.clientX-r.left-r.width/2)/45);y(-(e.clientY-r.top-r.height/2)/45);};const leave=()=>{x(0);y(0);};target.addEventListener('pointermove',move);target.addEventListener('pointerleave',leave);return()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerleave',leave);};});window.addEventListener('load',()=>ScrollTrigger.refresh(),{once:true});}
